basicCode.vanilla:
import { createDraftRestore } from '@/components/ui/draft-restore';

const faixa = createDraftRestore({
  labels: rotulos,
  draft: rascunhoGuardado,
  onAction: (action) => (action === 'restore' ? restaurar() : descartar()),
});

tela.prepend(faixa);

basicCode.react:
import { DraftRestore } from "@/components/ui/draft-restore";

<DraftRestore
  labels={rotulos}
  draft={rascunhoGuardado}
  onAction={(action) => (action === "restore" ? restaurar() : descartar())}
/>

withTimestampCode.web:
// A faixa NÃO guarda rascunho, não decide quando um expira e não diz o que
// descartar apaga. Ela mostra o que foi encontrado e avisa qual controle foi
// apertado; o resto é de quem consome.

// O carimbo chega JÁ ESCRITO. Formato de data é decisão de idioma, e um
// componente que o formatasse decidiria idioma em cinco lugares diferentes.
{ draft: rascunhoGuardado, timestamp: 'ontem, 14:32' }

// O rascunho vai INTEIRO. O corte de duas linhas é do desenho, e é o que
// mantém o texto achável pela busca do navegador e audível por completo.
{ draft: textoLongoInteiro }

extensibilityCode.web:
// O componente desenha o que RECEBE, e não sabe de onde o texto veio.
{
  draft: rascunhoGuardado,      // inteiro; o corte de duas linhas é do desenho
  timestamp: 'ontem, 14:32',    // já escrito — formato de data é de idioma
}

// A escolha sai como aviso, e o que ela significa é de quem consome:
// o que descartar apaga, se dá para desfazer, quando um rascunho expira.
onAction: (action) => (action === 'restore' ? restaurar() : descartar());

customizationCode.web:
/* Quantas linhas da prévia aparecem antes do corte. O corte é do desenho, e
   é isto que o mantém assim: o texto inteiro continua no documento em
   qualquer número de linhas. */
.nds-composer-draft-preview {
  -webkit-line-clamp: 3;
  line-clamp: 3;
}

/* Quando a faixa precisa de mais largura antes de os controles descerem
   para a linha de baixo. */
.nds-composer-draft-preview {
  flex-basis: 20rem;
}

