withTimestampCode.web:
// The band does NOT store drafts, does not decide when one expires and does
// not say what discarding erases. It shows what was found and reports which
// control was pressed; the rest belongs to whoever consumes it.

// The stamp arrives ALREADY WRITTEN. Date format is a language decision, and
// a component that formatted it would decide language in five places.
{ draft: rascunhoGuardado, timestamp: 'yesterday, 2:32 PM' }

// The draft goes in WHOLE. The two-line clipping belongs to the design, and
// that is what keeps the text findable by browser search and audible in full.
{ draft: textoLongoInteiro }

extensibilityCode.web:
// The component draws what it RECEIVES, and does not know where the text
// came from.
{
  draft: rascunhoGuardado,            // whole; the two-line clipping is design
  timestamp: 'yesterday, 2:32 PM',    // already written — date format is language
}

// The choice goes out as a notice, and what it means belongs to whoever
// consumes it: what discarding erases, whether it can be undone, when a
// draft expires.
onAction: (action) => (action === 'restore' ? restaurar() : descartar());

customizationCode.web:
/* How many lines of the preview show before the clipping. The clipping
   belongs to the design, and this is what keeps it that way: the whole text
   stays in the document at any number of lines. */
.nds-composer-draft-preview {
  -webkit-line-clamp: 3;
  line-clamp: 3;
}

/* When the band needs more width before the controls drop to the line
   below. */
.nds-composer-draft-preview {
  flex-basis: 20rem;
}

